"""Finalize auditable paired live measurements and the separate offline review projection."""
import hashlib,json,subprocess
from collections import Counter
from pathlib import Path
from r3_analyze import rows
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'bench/reports/r3-benchmark'
read=lambda name:json.loads((OUT/name).read_text(encoding='utf8'))
s=read('summary.json');projection=read('offline-projection.json');web=read('website-review.json');social=read('social-review.json')
head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
expected=[r['organisation_number'] for r in rows(ROOT/'bench/inputs/1000-r3/batch.jsonl')]
assert len(expected)==len(set(expected))==1000
