final={'narrowed_runtime_commit':head,'live_candidate_commit':s['candidate']['commit'],'mode':'Conservative offline projection only; not a third live run','metrics':{k:projection[k] for k in ('websites','social_companies','jobs','activity','facts')},'new_websites_retained':len(kept_web),'new_websites_by_proof':proofs,'new_websites_by_source':sources,'new_social_profiles_retained':len(kept_social),'new_social_companies_retained':sum(r['new_social_company'] and any(c['value']['url'] in projection['retained_social'][r['orgnr']] for c in r['social']) for r in social),'reviewed_website_gains':len(web),'reviewed_social_profiles':sum(len(r['social']) for r in social),'retained_review_verdicts':{'correct_websites':len(kept_web),'correct_social_profiles':len(kept_social),'wrong':0,'doubtful':0},'projection_baseline_losses':losses,'tests':{'passed':1259,'seconds':374.14},'removed_files':['src/signalpost/web/search.py','tests/test_search.py','tests/test_optional_brave.py','tests/test_bench_search_environment.py'],'limits':{'per_company_http':40,'pooled_per_input':18},'caveat':'Offline projection does not rerun registry uniqueness recovery, discover alternate candidates, regenerate summaries/profiles/site or measure final runtime. Seven baseline sites are conservatively withheld; this is not a measured seven-site runtime regression. Original live outputs remain untouched.'}
